class Solution:
    def meetRequirement(self, n: int, lights: List[List[int]], requirement: List[int]) -> int:
        diff = [0] * (n + 1)
        for pos, r in lights:
            diff[max(0, pos - r)] += 1
            diff[min(n - 1, pos + r) + 1] -= 1
        ans = cur = 0
        for i in range(n):
            cur += diff[i]
            if cur >= requirement[i]:
                ans += 1
        return ans

