class Solution {
public:
    int meetRequirement(int n, vector<vector<int>>& lights, vector<int>& requirement) {
        vector<int> diff(n + 1, 0);
        for (auto& lt : lights) {
            diff[max(0, lt[0] - lt[1])]++;
            diff[min(n - 1, lt[0] + lt[1]) + 1]--;
        }
        int ans = 0, cur = 0;
        for (int i = 0; i < n; ++i) {
            cur += diff[i];
            if (cur >= requirement[i]) ans++;
        }
        return ans;
    }
};

