class Solution {
public:
    int meetRequirement(int n, vector<vector<int>>& lights, vector<int>& requirement) {
        vector<pair<int,int>> ev;
        for (auto& lt : lights) {
            ev.push_back({max(0, lt[0] - lt[1]), 1});
            ev.push_back({min(n - 1, lt[0] + lt[1]) + 1, -1});
        }
        sort(ev.begin(), ev.end());
        int ans = 0, cur = 0, j = 0;
        for (int i = 0; i < n; ++i) {
            while (j < ev.size() && ev[j].first == i) cur += ev[j++].second;
            if (cur >= requirement[i]) ans++;
        }
        return ans;
    }
};

