class Solution {
    public int meetRequirement(int n, int[][] lights, int[] requirement) {
        List<int[]> ev = new ArrayList<>();
        for (int[] lt : lights) {
            ev.add(new int[]{Math.max(0, lt[0] - lt[1]), 1});
            ev.add(new int[]{Math.min(n - 1, lt[0] + lt[1]) + 1, -1});
        }
        ev.sort((a, b) -> a[0] != b[0] ? a[0] - b[0] : a[1] - b[1]);
        int ans = 0, cur = 0, j = 0;
        for (int i = 0; i < n; i++) {
            while (j < ev.size() && ev.get(j)[0] == i) cur += ev.get(j++)[1];
            if (cur >= requirement[i]) ans++;
        }
        return ans;
    }
}

